INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0005-0001-0001-000000000101', '22222222-0001-0001-0001-000000000005', 'What is a Percentage?', 'Discover how Roman tax collectors invented the idea of "per hundred"', 1, 'tutorial', 15, 5, -100, NULL,
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0501-0001-0001-000000000001', '33333333-0005-0001-0001-000000000101', 'multiple_choice', 'easy', 'What does "percent" literally mean?', NULL, '[{"id":"a","text":"Per ten"},{"id":"b","text":"Per hundred"},{"id":"c","text":"Per thousand"},{"id":"d","text":"Per part"}]'::jsonb, '"b"'::jsonb, '"Percent" comes from Latin "per centum" meaning "per hundred." So 25% means 25 out of every 100.', 'Think about the Latin word "centum"', 5, 1),
('44444444-0501-0001-0001-000000000002', '33333333-0005-0001-0001-000000000101', 'fill_in_blank', 'easy', 'Convert 50% to a decimal.', NULL, NULL, '"0.5"'::jsonb, '50% = 50/100 = 0.5. To convert a percentage to a decimal, divide by 100 (or move the decimal point two places left).', 'Divide by 100', 5, 2),
('44444444-0501-0001-0001-000000000003', '33333333-0005-0001-0001-000000000101', 'fill_in_blank', 'easy', 'Convert 0.75 to a percentage. (Just write the number, no % sign)', NULL, NULL, '"75"'::jsonb, '0.75 × 100 = 75%. To convert a decimal to a percentage, multiply by 100.', 'Multiply by 100', 5, 3),
('44444444-0501-0001-0001-000000000004', '33333333-0005-0001-0001-000000000101', 'multiple_choice', 'easy', 'What is 25% as a fraction in lowest terms?', NULL, '[{"id":"a","text":"1/4"},{"id":"b","text":"1/5"},{"id":"c","text":"2/5"},{"id":"d","text":"1/25"}]'::jsonb, '"a"'::jsonb, '25% = 25/100 = 1/4. Divide both numerator and denominator by 25.', '25 goes into 100 four times', 5, 4),
('44444444-0501-0001-0001-000000000005', '33333333-0005-0001-0001-000000000101', 'true_false', 'easy', 'True or False: 100% of something means all of it.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! 100% = 100/100 = 1, which is the whole thing. Similarly, 0% means none of it, and 50% means half.', 'What is 100 divided by 100?', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0005-0001-0001-000000000102', '22222222-0001-0001-0001-000000000005', 'Finding Percentages of Numbers', 'Calculate percentages of any number quickly and accurately', 2, 'practice', 15, 5, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0502-0001-0001-000000000001', '33333333-0005-0001-0001-000000000102', 'fill_in_blank', 'easy', 'What is 10% of 80?', NULL, NULL, '"8"'::jsonb, '10% of 80 = 0.10 × 80 = 8. Quick trick: to find 10%, just move the decimal one place left.', 'Move the decimal point one place left', 5, 1),
('44444444-0502-0001-0001-000000000002', '33333333-0005-0001-0001-000000000102', 'fill_in_blank', 'easy', 'What is 50% of 120?', NULL, NULL, '"60"'::jsonb, '50% = half. Half of 120 = 60.', '50% is the same as half', 5, 2),
('44444444-0502-0001-0001-000000000003', '33333333-0005-0001-0001-000000000102', 'fill_in_blank', 'medium', 'What is 25% of 200?', NULL, NULL, '"50"'::jsonb, '25% of 200 = 0.25 × 200 = 50. Or: 25% = 1/4, and 200 ÷ 4 = 50.', '25% is one quarter', 10, 3),
('44444444-0502-0001-0001-000000000004', '33333333-0005-0001-0001-000000000102', 'multiple_choice', 'medium', 'What is 15% of 60?', NULL, '[{"id":"a","text":"6"},{"id":"b","text":"9"},{"id":"c","text":"12"},{"id":"d","text":"15"}]'::jsonb, '"b"'::jsonb, '15% of 60 = 0.15 × 60 = 9. Or: 10% of 60 = 6, plus 5% of 60 = 3, total = 9.', 'Try finding 10% first, then add 5%', 10, 4),
('44444444-0502-0001-0001-000000000005', '33333333-0005-0001-0001-000000000102', 'fill_in_blank', 'medium', 'A shirt costs $40. It is on sale for 30% off. How much do you save? (Just the number)', NULL, NULL, '"12"'::jsonb, '30% of $40 = 0.30 × 40 = $12 savings.', '30% of 40 = ?', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0005-0001-0001-000000000103', '22222222-0001-0001-0001-000000000005', 'Percentage Increase & Decrease', 'Calculate how things grow and shrink using percentages', 3, 'practice', 15, 7, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0503-0001-0001-000000000001', '33333333-0005-0001-0001-000000000103', 'fill_in_blank', 'easy', 'A price goes from $50 to $60. What is the percentage increase? (Just the number)', NULL, NULL, '"20"'::jsonb, 'Increase = $10. Percentage increase = (10/50) × 100 = 20%.', 'Find the increase, then divide by the original', 5, 1),
('44444444-0503-0001-0001-000000000002', '33333333-0005-0001-0001-000000000103', 'multiple_choice', 'medium', 'A population decreases from 1000 to 800. What is the percentage decrease?', NULL, '[{"id":"a","text":"10%"},{"id":"b","text":"15%"},{"id":"c","text":"20%"},{"id":"d","text":"25%"}]'::jsonb, '"c"'::jsonb, 'Decrease = 200. Percentage decrease = (200/1000) × 100 = 20%.', 'The decrease is 200 out of the original 1000', 10, 2),
('44444444-0503-0001-0001-000000000003', '33333333-0005-0001-0001-000000000103', 'fill_in_blank', 'medium', 'A phone was $500 and increased by 10%. What is the new price? (Just the number)', NULL, NULL, '"550"'::jsonb, '10% of $500 = $50. New price = $500 + $50 = $550.', 'Find 10% of 500, then add it', 10, 3),
('44444444-0503-0001-0001-000000000004', '33333333-0005-0001-0001-000000000103', 'multiple_choice', 'medium', 'A $200 item is discounted by 25%. What is the sale price?', NULL, '[{"id":"a","text":"$175"},{"id":"b","text":"$150"},{"id":"c","text":"$125"},{"id":"d","text":"$160"}]'::jsonb, '"b"'::jsonb, '25% of $200 = $50 discount. Sale price = $200 - $50 = $150. Or: you pay 75% → 0.75 × 200 = $150.', 'You pay 100% - 25% = 75% of the price', 10, 4),
('44444444-0503-0001-0001-000000000005', '33333333-0005-0001-0001-000000000103', 'true_false', 'medium', 'True or False: If a price increases by 50% and then decreases by 50%, it returns to the original price.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'False! $100 + 50% = $150. Then $150 - 50% = $75. You end up LOWER than the start because the 50% decrease is calculated on the higher number.', 'The 50% decrease applies to the NEW (higher) price', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0005-0001-0001-000000000104', '22222222-0001-0001-0001-000000000005', 'Real-World Percentages', 'Apply percentage skills to everyday situations', 4, 'practice', 15, 5, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0504-0001-0001-000000000001', '33333333-0005-0001-0001-000000000104', 'fill_in_blank', 'easy', 'You scored 18 out of 20 on a test. What is your percentage score? (Just the number)', NULL, NULL, '"90"'::jsonb, '18/20 = 0.9 = 90%.', 'Divide 18 by 20, then multiply by 100', 5, 1),
('44444444-0504-0001-0001-000000000002', '33333333-0005-0001-0001-000000000104', 'multiple_choice', 'medium', 'A restaurant bill is $80. You want to leave a 15% tip. How much is the tip?', NULL, '[{"id":"a","text":"$8"},{"id":"b","text":"$10"},{"id":"c","text":"$12"},{"id":"d","text":"$15"}]'::jsonb, '"c"'::jsonb, '15% of $80 = 0.15 × 80 = $12. Quick method: 10% = $8, plus 5% = $4, total = $12.', 'Find 10% first ($8), then add half of that for 5%', 10, 2),
('44444444-0504-0001-0001-000000000003', '33333333-0005-0001-0001-000000000104', 'fill_in_blank', 'medium', 'A town has 2000 people. 35% are children. How many children are there? (Just the number)', NULL, NULL, '"700"'::jsonb, '35% of 2000 = 0.35 × 2000 = 700 children.', '0.35 × 2000', 10, 3),
('44444444-0504-0001-0001-000000000004', '33333333-0005-0001-0001-000000000104', 'multiple_choice', 'medium', 'Your phone battery is at 15% and the total capacity is 4000 mAh. How much charge remains?', NULL, '[{"id":"a","text":"400 mAh"},{"id":"b","text":"500 mAh"},{"id":"c","text":"600 mAh"},{"id":"d","text":"800 mAh"}]'::jsonb, '"c"'::jsonb, '15% of 4000 = 0.15 × 4000 = 600 mAh remaining.', '15% of 4000', 10, 4),
('44444444-0504-0001-0001-000000000005', '33333333-0005-0001-0001-000000000104', 'fill_in_blank', 'hard', 'An item costs $120 after a 20% discount. What was the original price? (Just the number)', NULL, NULL, '"150"'::jsonb, 'After a 20% discount, you pay 80% of the original. So original = $120 ÷ 0.80 = $150.', '$120 is 80% of what number?', 15, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0005-0001-0001-000000000105', '22222222-0001-0001-0001-000000000005', 'Percentages Boss', 'Test your percentage mastery!', 5, 'boss_round', 30, 5, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0505-0001-0001-000000000001', '33333333-0005-0001-0001-000000000105', 'fill_in_blank', 'medium', 'What is 12.5% as a fraction in lowest terms? (Write as a fraction)', NULL, NULL, '"1/8"'::jsonb, '12.5% = 12.5/100 = 125/1000 = 1/8.', '12.5 × 8 = 100', 10, 1),
('44444444-0505-0001-0001-000000000002', '33333333-0005-0001-0001-000000000105', 'multiple_choice', 'medium', 'A jacket was $80, then marked up 25%, then discounted 20%. What is the final price?', NULL, '[{"id":"a","text":"$80"},{"id":"b","text":"$76"},{"id":"c","text":"$84"},{"id":"d","text":"$75"}]'::jsonb, '"a"'::jsonb, 'Markup: $80 × 1.25 = $100. Discount: $100 × 0.80 = $80. Back to the original! (But this is a coincidence of the specific numbers, not a general rule.)', 'First apply the 25% increase, then the 20% decrease', 10, 2),
('44444444-0505-0001-0001-000000000003', '33333333-0005-0001-0001-000000000105', 'fill_in_blank', 'hard', 'Sales tax is 8%. You buy something for $25. What is the total including tax? (Include decimal)', NULL, NULL, '"27"'::jsonb, 'Tax = 8% of $25 = $2. Total = $25 + $2 = $27.', '8% of 25 = 2', 15, 3),
('44444444-0505-0001-0001-000000000004', '33333333-0005-0001-0001-000000000105', 'multiple_choice', 'hard', 'A city grows from 50,000 to 65,000 people. What is the percentage growth?', NULL, '[{"id":"a","text":"15%"},{"id":"b","text":"23%"},{"id":"c","text":"30%"},{"id":"d","text":"25%"}]'::jsonb, '"c"'::jsonb, 'Growth = 15,000. Percentage = (15,000/50,000) × 100 = 30%.', 'Divide the growth by the original population', 15, 4),
('44444444-0505-0001-0001-000000000005', '33333333-0005-0001-0001-000000000105', 'fill_in_blank', 'hard', 'You invest $1000 at 5% interest for 1 year. How much interest do you earn? (Just the number)', NULL, NULL, '"50"'::jsonb, '5% of $1000 = 0.05 × 1000 = $50.', '5% of 1000', 15, 5)
